    private boolean canReach(int[] nums, int i) {
        int last = nums.length - 1;
        if (i == last) return true;
        for (int step = Math.min(nums[i], last - i); step >= 1; step--)
            if (canReach(nums, i + step)) return true;
        return false;
    }
}

