        for (int i = 0; i < m; i++)
            for (int a = 0; a <= n; a++) {
                if (dp[i][a] == INF) continue;
                dp[i + 1][a] = min(dp[i + 1][a], dp[i][a] + costs[i][1]);
                if (a < n) dp[i + 1][a + 1] = min(dp[i + 1][a + 1], dp[i][a] + costs[i][0]);
            }
        return dp[m][n];
    }
